import React, { useState, useRef, useEffect } from 'react';
import useFetch from '../hooks/useFetch';
import api from '../services/api';
import BackButton from '../components/BackButton';
import { QRCodeCanvas } from 'qrcode.react';
import FaceRegistration from '../components/FaceRegistration';

const Employees = () => {
  const { data: users, loading, refetch } = useFetch('/users');
  const [showForm, setShowForm] = useState(false);
  const [editingUser, setEditingUser] = useState(null);
  const [qrUser, setQrUser] = useState(null); // State for user whose QR is being viewed
  const [formData, setFormData] = useState({
    full_name: '',
    email: '',
    role: 'employee',
    department: '',
    password: '',
    salary: '',
    sex: ''
  });
  const [submitting, setSubmitting] = useState(false);

  // Face ID state
  const [faceDescriptor, setFaceDescriptor] = useState(null);
  const [showFaceModal, setShowFaceModal] = useState(false);// ... (existing handlers: handleSubmit, handleEdit, handleDeactivate, handleActivate, formatCurrency) ...
  const handleSubmit = async (e) => {
    e.preventDefault();
    setSubmitting(true);
    try {
      // Create FormData for file upload (both create and update)
      const submitData = new FormData();
      Object.keys(formData).forEach(key => {
        if (formData[key]) { // Only append non-empty values
          submitData.append(key, formData[key]);
        }
      });

      // Add Face Descriptor if captured
      if (faceDescriptor) {
        submitData.append('face_descriptor', JSON.stringify(faceDescriptor));
        console.log('✅ Adding face descriptor to upload');
      } else {
        console.log('⚠️ No face descriptor captured');
      }

      // Debug: Log FormData contents
      console.log('📤 Submitting FormData with fields:', Array.from(submitData.keys()));

      if (editingUser) {
        const response = await api.put(`/users/${editingUser.user_id}`, submitData, {
          headers: { 'Content-Type': 'multipart/form-data' }
        });
        console.log('✅ Update response:', response.data);
        alert('Employee updated successfully');
      } else {
        const response = await api.post('/users', submitData, {
          headers: { 'Content-Type': 'multipart/form-data' }
        });
        console.log('✅ Create response:', response.data);
        alert('Employee registered successfully');
      }
      setShowForm(false);
      setEditingUser(null);
      setFormData({ full_name: '', email: '', role: 'employee', department: '', password: '', salary: '', sex: '' });
      setFaceDescriptor(null);
      refetch();
    } catch (error) {
      console.error('❌ Submit error:', error);
      console.error('Error response:', error.response?.data);
      alert('Failed to save employee: ' + (error.response?.data?.message || error.message));
    } finally {
      setSubmitting(false);
    }
  };

  const handleEdit = (user) => {
    setEditingUser(user);
    setFormData({
      full_name: user.full_name,
      email: user.email,
      role: user.role,
      department: user.department || '',
      password: '',
      salary: user.salary || '',
      sex: user.sex || ''
    });
    // Load existing face descriptor if available
    if (user.face_descriptor) {
      try {
        setFaceDescriptor(typeof user.face_descriptor === 'string' ? JSON.parse(user.face_descriptor) : user.face_descriptor);
      } catch (e) {
        console.error('Failed to parse descriptor', e);
        setFaceDescriptor(null);
      }
    } else {
      setFaceDescriptor(null);
    }
    setShowForm(true);
  };

  const handleDeactivate = async (userId) => {
    if (window.confirm('Are you sure you want to deactivate this employee?')) {
      try {
        await api.put(`/users/${userId}`, { status: 'inactive' });
        alert('Employee deactivated');
        refetch();
      } catch (error) {
        alert('Failed to deactivate employee');
      }
    }
  };

  const handleActivate = async (userId) => {
    try {
      await api.put(`/users/${userId}`, { status: 'active' });
      alert('Employee activated');
      refetch();
    } catch (error) {
      alert('Failed to activate employee');
    }
  };

  const formatCurrency = (amount) => {
    if (!amount) return '-';
    return `${parseFloat(amount).toLocaleString('en-ET')} ETB`;
  };

  const downloadQR = () => {
    const canvas = document.querySelector('canvas');
    if (canvas && qrUser) {
      const pngUrl = canvas.toDataURL('image/png');
      const downloadLink = document.createElement('a');
      downloadLink.href = pngUrl;
      downloadLink.download = `attendance_qr_${qrUser.full_name.replace(/\s+/g, '_')}.png`;
      document.body.appendChild(downloadLink);
      downloadLink.click();
      document.body.removeChild(downloadLink);
    }
  };

  const handleFaceRegister = (descriptor) => {
    setFaceDescriptor(descriptor);
    setShowFaceModal(false);
  };

  const handleCloseForm = () => {
    setFaceDescriptor(null);
    setShowForm(false);
    setEditingUser(null);
    setFormData({ full_name: '', email: '', role: 'employee', department: '', password: '', salary: '', sex: '' });
  };

  if (loading) return <div className="flex items-center justify-center min-h-screen">Loading...</div>;

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto">
        <BackButton />
        <div className="mb-8 flex justify-between items-center">
          <div>
            <h1 className="text-4xl font-bold text-gray-900 mb-2">Employees</h1>
            <p className="text-gray-600">Manage your workforce</p>
          </div>
          <button
            onClick={() => {
              setEditingUser(null);
              setFormData({ full_name: '', email: '', role: 'employee', department: '', password: '', salary: '', sex: '' });
              setShowForm(true);
            }}
            className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg font-medium"
          >
            Add Employee
          </button>
        </div>

        {/* QR Code Modal using generic overlay logic */}
        {qrUser && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black bg-opacity-50 backdrop-blur-sm fade-in">
            <div className="bg-white rounded-2xl shadow-2xl p-6 w-full max-w-sm flex flex-col items-center slide-up relative">
              <button
                onClick={() => setQrUser(null)}
                className="absolute top-4 right-4 text-gray-400 hover:text-gray-600"
              >
                ✕
              </button>
              <h3 className="text-xl font-bold text-gray-900 mb-2">{qrUser.full_name}</h3>
              <p className="text-sm text-gray-500 mb-6">{qrUser.role} - {qrUser.department}</p>

              <div className="p-4 bg-white rounded-xl shadow-inner border border-gray-100 mb-6">
                <QRCodeCanvas
                  value={JSON.stringify({ id: qrUser.user_id, type: 'attendance_qr' })}
                  size={200}
                  level="H"
                />
              </div>

              <button
                onClick={downloadQR}
                className="mb-4 flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg font-medium transition-colors shadow-sm w-full justify-center"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                Download Image
              </button>

              <p className="text-center text-xs text-gray-400">
                Scan this code at the kiosk to check in/out
              </p>
            </div>
          </div>
        )}

        {showForm && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black bg-opacity-50 backdrop-blur-sm fade-in">
            <div className="bg-white p-6 rounded-xl shadow-2xl w-full max-w-2xl slide-up relative overflow-y-auto max-h-[90vh]">
              <button
                onClick={handleCloseForm}
                className="absolute top-4 right-4 text-gray-500 hover:text-gray-700 transition-colors"
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
              </button>

              <h2 className="text-2xl font-bold text-gray-900 mb-6 border-b pb-2">
                {editingUser ? 'Edit Employee' : 'Register New Employee'}
              </h2>

              <form onSubmit={handleSubmit} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-1">Full Name <span className="text-red-500">*</span></label>
                    <input
                      type="text"
                      value={formData.full_name}
                      onChange={(e) => setFormData({ ...formData, full_name: e.target.value })}
                      className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-shadow"
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-1">Email <span className="text-red-500">*</span></label>
                    <input
                      type="email"
                      value={formData.email}
                      onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                      className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-shadow"
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-1">Role <span className="text-red-500">*</span></label>
                    <select
                      value={formData.role}
                      onChange={(e) => setFormData({ ...formData, role: e.target.value })}
                      className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-shadow"
                      required
                    >
                      <option value="employee">Employee</option>
                      <option value="hr">HR</option>
                      <option value="admin">Admin</option>
                      <option value="attendance_manager">Attendance Manager</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-1">Sex <span className="text-red-500">*</span></label>
                    <select
                      value={formData.sex || ''}
                      onChange={(e) => setFormData({ ...formData, sex: e.target.value })}
                      className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-shadow"
                      required
                    >
                      <option value="">Select Sex</option>
                      <option value="Male">Male</option>
                      <option value="Female">Female</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-1">Department <span className="text-red-500">*</span></label>
                    <input
                      type="text"
                      value={formData.department}
                      onChange={(e) => setFormData({ ...formData, department: e.target.value })}
                      className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-shadow"
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-1">
                      Monthly Salary (ETB) <span className="text-red-500">*</span>
                    </label>
                    <input
                      type="number"
                      value={formData.salary}
                      onChange={(e) => setFormData({ ...formData, salary: e.target.value })}
                      className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-shadow"
                      placeholder="e.g. 15000"
                      required
                      min="0"
                    />
                  </div>
                  {!editingUser && (
                    <div className="md:col-span-2">
                      <label className="block text-sm font-semibold text-gray-700 mb-1">Password <span className="text-red-500">*</span></label>
                      <input
                        type="password"
                        value={formData.password}
                        onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                        className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-shadow"
                        required
                        minLength="6"
                      />
                      <p className="text-xs text-gray-500 mt-1">Minimum 6 characters</p>
                    </div>
                  )}

                  {/* Face ID Registration Section */}
                  <div className="md:col-span-2">
                    <label className="block text-sm font-semibold text-gray-700 mb-2">
                      Face ID Registration
                    </label>

                    <div className="flex items-center gap-4">
                      <button
                        type="button"
                        onClick={() => setShowFaceModal(true)}
                        className={`flex-1 flex items-center justify-center gap-2 px-4 py-3 rounded-lg font-medium border-2 border-dashed transition-colors ${faceDescriptor
                          ? 'bg-green-50 border-green-300 text-green-700'
                          : 'bg-indigo-50 border-indigo-300 text-indigo-700 hover:bg-indigo-100 hover:border-indigo-400'
                          }`}
                      >
                        {faceDescriptor ? (
                          <>
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg>
                            <span>Face ID Registered</span>
                          </>
                        ) : (
                          <>
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14.828 14.828a4 4 0 01-5.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                            <span>Register Face ID</span>
                          </>
                        )}
                      </button>

                      {faceDescriptor && (
                        <button
                          type="button"
                          onClick={() => setFaceDescriptor(null)}
                          className="px-4 py-3 text-red-600 hover:text-red-700 hover:bg-red-50 border border-red-200 rounded-lg font-medium transition-colors"
                        >
                          Clear
                        </button>
                      )}
                    </div>
                    <p className="text-xs text-gray-500 mt-2">
                      Scan the employee's face to enable fast attendance check-in.
                    </p>
                  </div>
                </div>

                <div className="flex justify-end space-x-3 pt-4 border-t mt-4">
                  <button
                    type="button"
                    onClick={() => setShowForm(false)}
                    className="px-6 py-2.5 text-gray-700 font-medium hover:bg-gray-100 rounded-lg transition-colors border border-gray-300"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    disabled={submitting}
                    className="px-6 py-2.5 bg-gradient-to-r from-blue-600 to-indigo-600 text-white font-medium hover:from-blue-700 hover:to-indigo-700 rounded-lg transition-all shadow-md disabled:opacity-50 disabled:cursor-not-allowed flex items-center"
                  >
                    {submitting && (
                      <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                      </svg>
                    )}
                    {editingUser ? 'Update Employee' : 'Register Employee'}
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}

        <div className="bg-white rounded-xl shadow-lg overflow-hidden border border-gray-100">
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase">Name</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase">Email</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase">Role</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase">Sex</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase">Department</th>
                  <th className="px-6 py-4 text-right text-xs font-medium text-gray-500 uppercase">Salary</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {users?.map((user) => (
                  <tr key={user.user_id} className="hover:bg-gray-50">
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{user.full_name}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{user.email}</td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`px-2 py-1 text-xs font-semibold rounded-full ${user.role === 'admin' ? 'bg-purple-100 text-purple-800' :
                        user.role === 'hr' ? 'bg-blue-100 text-blue-800' :
                          user.role === 'attendance_manager' ? 'bg-indigo-100 text-indigo-800' :
                            'bg-green-100 text-green-800'
                        }`}>{user.role}</span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{user.sex || '-'}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{user.department || '-'}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-right font-medium text-green-700">
                      {formatCurrency(user.salary)}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`px-2 py-1 text-xs font-semibold rounded-full ${user.status === 'active' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
                        }`}>{user.status}</span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                      <div className="flex space-x-2">
                        <button
                          onClick={() => setQrUser(user)}
                          className="bg-purple-100 text-purple-700 border border-purple-200 px-3 py-1 rounded-md hover:bg-purple-200 transition-colors font-medium text-xs flex items-center gap-1"
                        >
                          <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v1m6 11h2m-6 0h-2v4h-4v-2h-4v2H6v-4H4v-4h2v-2h4v2h2v4h2v-4h2v4h2v-4h2v2h-2v2h2v2h-2v-2z" /></svg>
                          QR Code
                        </button>
                        <button onClick={() => handleEdit(user)} className="text-blue-600 hover:text-blue-900 ml-2">Edit</button>
                        {user.status === 'active' ? (
                          <button onClick={() => handleDeactivate(user.user_id)} className="text-red-600 hover:text-red-900">Deactivate</button>
                        ) : (
                          <button onClick={() => handleActivate(user.user_id)} className="text-green-600 hover:text-green-900">Activate</button>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
      {showFaceModal && (
        <FaceRegistration
          onClose={() => setShowFaceModal(false)}
          onRegister={handleFaceRegister}
        />
      )}
    </div>
  );
};

export default Employees;